import java.util.HashMap;
import java.util.Map;
import java.util.Optional;
import java.util.function.Function;

public class Main {
    static final class Repository<T, ID> {
        private final Map<ID, T> data = new HashMap<>();
        private final Function<T, ID> idOf;
        Repository(Function<T, ID> idOf) { this.idOf = idOf; }
        void save(T item) { data.put(idOf.apply(item), item); }
        Optional<T> findById(ID id) { return Optional.ofNullable(data.get(id)); }
    }
    record User(long id, String name) { }
    public static void main(String[] args) {
        Repository<User, Long> users = new Repository<>(User::id);
        users.save(new User(1, "Ada"));
        System.out.println(users.findById(1L).orElseThrow().name());
    }
}
